// Obtiene el item original y completo del nodo del formulario
const formItem = $('Application Form').item;

// Crea un nuevo item de datos para la salida
const newItem = {
  json: {},
  binary: {}
};

// Copia toda la información de texto (Nombre, Email, etc.)
if (formItem.json) {
  newItem.json = formItem.json;
}

// Revisa si el archivo existe y lo copia
if (formItem.binary && formItem.binary.Cargar_CV) {
  newItem.binary.Cargar_CV = formItem.binary.Cargar_CV;
}

// Devuelve el nuevo item completo como la salida del nodo
return [newItem];
